+void AbstractNotificationsModel::snooze(uint notificationId, std::chrono::milliseconds duration)
+{
+    const int row = rowOfNotification(notificationId);
+    if (row == -1) {
+        return;
+    }
+
+    // Hide the popup without closing the notification, so its actions keep working from the history
+    setData(index(row, 0), true, Notifications::ExpiredRole);
+
+    QTimer *timer = d->snoozeTimers.value(notificationId);
+    if (!timer) {
+        timer = new QTimer();
+        timer->setSingleShot(true);
+
+        connect(timer, &QTimer::timeout, this, [this, notificationId] {
+            d->snoozeTimers.take(notificationId)->deleteLater();
+
+            const int row = rowOfNotification(notificationId);
+            if (row == -1) {
+                return;
+            }
+
+            const QModelIndex idx = index(row, 0);
+            setData(idx, false, Notifications::ReadRole);
+            setData(idx, false, Notifications::ExpiredRole);
+        });
+        d->snoozeTimers.insert(notificationId, timer);
+    }
+
+    timer->start(duration);
+}
